"""
Aggregates raw per-node readings into a single field moisture estimate.
"""

import json
import statistics

from sensor_reader import (
    ProbeConfig,
    SensorTimeoutError,
    parse_reading,
    poll_sensor_raw,
)


class ProbeConfigError(Exception):
    pass


def load_probe_configs(path):
    try:
        with open(path) as f:
            raw = json.load(f)
    except FileNotFoundError as exc:
        raise ProbeConfigError(f"calibration file not found: {path}") from exc

    configs = {}
    for entry in raw:
        configs[entry["node_id"]] = ProbeConfig(
            node_id=entry["node_id"],
            probe_length_cm=entry["probe_length_cm"],
            freq_slope=entry["freq_slope"],
            freq_intercept=entry["freq_intercept"],
        )
    return configs


def compute_field_moisture_average(node_ids, radio, probe_configs):
    """Poll every node in the field and average the successful readings.

    A node that fails to report during a given cycle is simply excluded
    from that cycle's average rather than aborting the whole reading, since
    the odd missed poll is a normal part of running probes over a lossy
    field radio link.
    """
    readings = []
    skipped = 0
    for node_id in node_ids:
        config = probe_configs[node_id]
        try:
            raw_count = poll_sensor_raw(node_id, radio)
            vwc = parse_reading(node_id, raw_count, config)
            readings.append(vwc)
        except (SensorTimeoutError, ValueError, ZeroDivisionError):
            skipped += 1
            continue

    if not readings:
        raise ProbeConfigError("no field nodes returned a usable reading")

    if skipped > len(node_ids) // 2:
        print(f"warning: {skipped} of {len(node_ids)} nodes skipped this cycle")

    return statistics.mean(readings)


def evaluate_field(node_ids, radio, probe_configs):
    """Return the field's current average volumetric water content."""
    return compute_field_moisture_average(node_ids, radio, probe_configs)

"""
Entry point: decide which field zones need irrigation this cycle.
"""

from calibration import ProbeConfigError, evaluate_field

MIN_SENSORS_REQUIRED = 3


def should_irrigate(node_ids, radio, probe_configs, moisture_threshold):
    if len(node_ids) < MIN_SENSORS_REQUIRED:
        raise ValueError(
            f"zone has only {len(node_ids)} configured probes; "
            f"at least {MIN_SENSORS_REQUIRED} are needed for a reliable reading"
        )

    average_vwc = evaluate_field(node_ids, radio, probe_configs)
    return average_vwc < moisture_threshold


def run_irrigation_cycle(zones, radio, probe_configs, moisture_threshold):
    """Check every zone in the field and return the ones that need water."""
    zones_to_water = []
    for zone_name, node_ids in zones.items():
        try:
            if should_irrigate(node_ids, radio, probe_configs, moisture_threshold):
                zones_to_water.append(zone_name)
        except ProbeConfigError as exc:
            print(f"skipping zone {zone_name}: {exc}")
    return zones_to_water
